// stt-adapter-moonshine — Moonshine (ONNX Runtime) model adapter.
//
// Implements the model side of stt-adapter/1 (docs/CONTRATOS.md):
//   - reads the JSON protocol header from stdin
//   - loads Moonshine encoder + merged decoder (ONNX Runtime C++ API)
//   - emits "ready"
//   - reads length-prefixed PCM frames (s16le / 16 kHz / mono)
//   - transcribes each frame and emits one "final" event per frame
//   - on stdin EOF emits "bye" and exits 0
//
// Model directory (--model DIR) must contain:
//   encoder_model.onnx, decoder_model_merged.onnx, vocab.tsv
// vocab.tsv is generated by scripts/fetch-model.sh ("id<TAB>token" lines).
//
// Build: make -C adapters/moonshine

#include <onnxruntime_cxx_api.h>

#include <cctype>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <memory>
#include <stdexcept>
#include <string>
#include <sys/resource.h>
#include <vector>

namespace {

constexpr int kSampleRate = 16000;
constexpr int kChannels = 1;
constexpr int kBytesPerSample = 2;

// Moonshine tokenizer / model constants (see ctranslate2/tiny/tokenizer.json).
constexpr int kStartToken = 1; // <s>
constexpr int kEosToken = 2;   // </s>
constexpr int kDefaultMaxTokens = 192;
constexpr double kMinAudioS = 0.1;
constexpr double kChunkAudioS = 60.0; // Moonshine supports up to 64 s per call
// Moonshine-tiny occasionally emits EOS (empty text) for speech-bearing audio
// of unlucky durations (verified against the Python reference). Retry empty
// results on edge-trimmed audio: a different duration changes the encoder
// behavior. Deterministically silent audio still stays empty. Trims are
// capped at a quarter of the frame so at least half the audio is kept.
constexpr size_t kRetryTrimS = 3;
constexpr size_t kRetryTrimSamples = kRetryTrimS * 160; // 100 ms per step

struct Options {
    std::string model_dir = "var/models/moonshine-tiny";
    std::string encoder;
    std::string decoder;
    std::string vocab;
    int threads = 4;
    int max_tokens = kDefaultMaxTokens;
};

// ---------------------------------------------------------------- utilities

bool read_full(FILE *f, void *buf, size_t n) {
    return n == 0 || std::fread(buf, 1, n, f) == n;
}

bool read_line(FILE *f, std::string &line) {
    line.clear();
    int c;
    bool any = false;
    while ((c = std::fgetc(f)) != EOF) {
        any = true;
        if (c == '\n') return true;
        line.push_back(static_cast<char>(c));
        if (line.size() > (1u << 20)) return false;
    }
    return any;
}

// Extracts the integer that follows `"key":` in a single-line JSON object.
bool json_int(const std::string &json, const std::string &key, long *out) {
    size_t p = json.find("\"" + key + "\"");
    if (p == std::string::npos) return false;
    p = json.find(':', p + key.size() + 2);
    if (p == std::string::npos) return false;
    const char *s = json.c_str() + p + 1;
    char *end = nullptr;
    long v = std::strtol(s, &end, 10);
    if (end == s) return false;
    *out = v;
    return true;
}

void json_escape(FILE *f, const std::string &s) {
    for (unsigned char c : s) {
        switch (c) {
        case '"': std::fputs("\\\"", f); break;
        case '\\': std::fputs("\\\\", f); break;
        case '\n': std::fputs("\\n", f); break;
        case '\r': std::fputs("\\r", f); break;
        case '\t': std::fputs("\\t", f); break;
        default:
            if (c < 0x20) {
                std::fprintf(f, "\\u%04x", c);
            } else {
                std::fputc(c, f);
            }
        }
    }
}

void emit_error(const std::string &code, const std::string &message, bool fatal) {
    std::fputs("{\"type\":\"error\",\"code\":\"", stdout);
    json_escape(stdout, code);
    std::fputs("\",\"message\":\"", stdout);
    json_escape(stdout, message);
    std::fprintf(stdout, "\",\"fatal\":%s}\n", fatal ? "true" : "false");
    std::fflush(stdout);
}

std::string utf8_sanitize(const std::string &in) {
    std::string out;
    out.reserve(in.size());
    size_t i = 0, n = in.size();
    while (i < n) {
        unsigned char c = static_cast<unsigned char>(in[i]);
        if (c < 0x80) {
            out.push_back(static_cast<char>(c));
            ++i;
            continue;
        }
        int len = 0;
        if (c >= 0xC2 && c <= 0xDF) len = 2;
        else if (c >= 0xE0 && c <= 0xEF) len = 3;
        else if (c >= 0xF0 && c <= 0xF4) len = 4;
        bool ok = len > 0 && i + static_cast<size_t>(len) <= n;
        if (ok) {
            for (int k = 1; k < len; ++k) {
                if ((static_cast<unsigned char>(in[i + k]) & 0xC0) != 0x80) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok && len == 3) {
            unsigned char c1 = static_cast<unsigned char>(in[i + 1]);
            if (c == 0xE0 && c1 < 0xA0) ok = false;
            if (c == 0xED && c1 >= 0xA0) ok = false;
        }
        if (ok && len == 4) {
            unsigned char c1 = static_cast<unsigned char>(in[i + 1]);
            if (c == 0xF0 && c1 < 0x90) ok = false;
            if (c == 0xF4 && c1 >= 0x90) ok = false;
        }
        if (ok) {
            out.append(in, i, static_cast<size_t>(len));
            i += static_cast<size_t>(len);
        } else {
            out += "\xEF\xBF\xBD"; // U+FFFD
            ++i;
        }
    }
    return out;
}

// ---------------------------------------------------------------- tokenizer

// Decodes token ids to text. This is the decode side of the SentencePiece-style
// tokenizer used by Moonshine: "▁" -> space, "<0xNN>" -> byte, strip one
// leading space (matches tokenizers' Sequence decoder).
class Tokenizer {
  public:
    bool load(const std::string &path, std::string *err) {
        FILE *f = std::fopen(path.c_str(), "rb");
        if (!f) {
            *err = "cannot open vocab: " + path;
            return false;
        }
        char *line = nullptr;
        size_t cap = 0;
        ssize_t n;
        while ((n = ::getline(&line, &cap, f)) > 0) {
            while (n > 0 && (line[n - 1] == '\n' || line[n - 1] == '\r')) line[--n] = '\0';
            char *tab = static_cast<char *>(std::memchr(line, '\t', static_cast<size_t>(n)));
            if (!tab) continue;
            int id = std::atoi(line);
            if (id < 0) continue;
            if (static_cast<size_t>(id) >= vocab_.size()) vocab_.resize(static_cast<size_t>(id) + 1);
            vocab_[static_cast<size_t>(id)] = std::string(tab + 1);
        }
        std::free(line);
        std::fclose(f);
        if (vocab_.empty()) {
            *err = "vocab is empty: " + path;
            return false;
        }
        return true;
    }

    std::string decode(const std::vector<int> &ids) const {
        std::string bytes;
        bytes.reserve(ids.size() * 4);
        for (int id : ids) {
            if (id < 0 || static_cast<size_t>(id) >= vocab_.size()) continue;
            if (id == kStartToken || id == kEosToken || id == 0) continue; // specials
            const std::string &t = vocab_[static_cast<size_t>(id)];
            if (t.size() == 6 && t[0] == '<' && t[1] == '0' && t[2] == 'x' && t[5] == '>' &&
                std::isxdigit(static_cast<unsigned char>(t[3])) &&
                std::isxdigit(static_cast<unsigned char>(t[4]))) {
                bytes.push_back(static_cast<char>(std::strtol(t.substr(3, 2).c_str(), nullptr, 16)));
                continue;
            }
            for (size_t i = 0; i < t.size();) {
                // U+2581 LOWER ONE EIGHTH BLOCK ("▁", UTF-8 E2 96 81) -> space.
                if (i + 2 < t.size() && static_cast<unsigned char>(t[i]) == 0xE2 &&
                    static_cast<unsigned char>(t[i + 1]) == 0x96 &&
                    static_cast<unsigned char>(t[i + 2]) == 0x81) {
                    bytes.push_back(' ');
                    i += 3;
                } else {
                    bytes.push_back(t[i]);
                    ++i;
                }
            }
        }
        if (!bytes.empty() && bytes[0] == ' ') bytes.erase(0, 1);
        return utf8_sanitize(bytes);
    }

  private:
    std::vector<std::string> vocab_;
};

// ---------------------------------------------------------------- model

int kv_kind(const std::string &name, const char *prefix, int *layer) {
    // "<prefix>.<layer>.<decoder|encoder>.<key|value>"
    size_t p = std::strlen(prefix);
    if (name.compare(0, p, prefix) != 0) return -1;
    int l = 0;
    if (std::sscanf(name.c_str() + p, ".%d.", &l) != 1) return -1;
    *layer = l;
    if (name.find(".decoder.key") != std::string::npos) return 0;
    if (name.find(".decoder.value") != std::string::npos) return 1;
    if (name.find(".encoder.key") != std::string::npos) return 2;
    if (name.find(".encoder.value") != std::string::npos) return 3;
    return -1;
}

struct Model {
    Ort::Env env;
    Ort::SessionOptions opts;
    Ort::MemoryInfo mem;
    std::unique_ptr<Ort::Session> encoder;
    std::unique_ptr<Ort::Session> decoder;

    std::vector<std::string> enc_in_names, enc_out_names, dec_in_names, dec_out_names;

    int enc_input_values = -1;
    int enc_attention_mask = -1;
    int enc_hidden_out = -1;

    int dec_input_ids = -1;
    int dec_hidden = -1;
    int dec_use_cache = -1;
    int dec_encoder_mask = -1;
    int dec_logits = -1;

    int num_layers = 0;
    int num_heads = 0;
    int head_dim = 0;
    std::vector<int> kv_in_idx;       // slot -> decoder input index
    std::vector<int> present_out_idx; // slot -> decoder output index

    Model(const std::string &enc_path, const std::string &dec_path, int threads)
        : env(ORT_LOGGING_LEVEL_WARNING, "stt-adapter-moonshine"),
          mem(Ort::MemoryInfo::CreateCpu(OrtArenaAllocator, OrtMemTypeDefault)) {
        opts.SetIntraOpNumThreads(threads);
        opts.SetInterOpNumThreads(1);
        opts.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_ALL);
        opts.SetExecutionMode(ExecutionMode::ORT_SEQUENTIAL);
        // Weight prepacking costs ~45 MB of RSS on this device (301 MB vs 256 MB
        // peak) for a ~1.5x faster decode. Memory wins: RTF stays well below the
        // 0.35 objective. See ARQUITECTURA.md D7.
        opts.AddConfigEntry("session.disable_prepacking", "1");

        encoder.reset(new Ort::Session(env, enc_path.c_str(), opts));
        decoder.reset(new Ort::Session(env, dec_path.c_str(), opts));

        Ort::AllocatorWithDefaultOptions alloc;
        for (size_t i = 0; i < encoder->GetInputCount(); ++i)
            enc_in_names.push_back(encoder->GetInputNameAllocated(i, alloc).get());
        for (size_t i = 0; i < encoder->GetOutputCount(); ++i)
            enc_out_names.push_back(encoder->GetOutputNameAllocated(i, alloc).get());
        for (size_t i = 0; i < decoder->GetInputCount(); ++i)
            dec_in_names.push_back(decoder->GetInputNameAllocated(i, alloc).get());
        for (size_t i = 0; i < decoder->GetOutputCount(); ++i)
            dec_out_names.push_back(decoder->GetOutputNameAllocated(i, alloc).get());

        for (int i = 0; i < static_cast<int>(enc_in_names.size()); ++i) {
            if (enc_in_names[i] == "input_values") enc_input_values = i;
            else if (enc_in_names[i] == "attention_mask") enc_attention_mask = i;
        }
        for (int i = 0; i < static_cast<int>(enc_out_names.size()); ++i) {
            if (enc_out_names[i] == "last_hidden_state") enc_hidden_out = i;
        }

        int max_layer = -1;
        for (int i = 0; i < static_cast<int>(dec_in_names.size()); ++i) {
            const std::string &n = dec_in_names[i];
            int layer = 0;
            int kind = kv_kind(n, "past_key_values", &layer);
            if (kind >= 0) {
                if (layer > max_layer) max_layer = layer;
                continue;
            }
            if (n == "input_ids") dec_input_ids = i;
            else if (n == "encoder_hidden_states") dec_hidden = i;
            else if (n == "use_cache_branch") dec_use_cache = i;
            else if (n == "encoder_attention_mask") dec_encoder_mask = i;
        }
        for (int i = 0; i < static_cast<int>(dec_out_names.size()); ++i) {
            if (dec_out_names[i] == "logits") dec_logits = i;
        }
        num_layers = max_layer + 1;
        if (num_layers <= 0 || dec_input_ids < 0 || dec_hidden < 0 || dec_use_cache < 0 ||
            dec_logits < 0 || enc_input_values < 0 || enc_hidden_out < 0) {
            throw std::runtime_error("unexpected ONNX model interface (not a Moonshine export?)");
        }

        kv_in_idx.assign(static_cast<size_t>(num_layers) * 4, -1);
        present_out_idx.assign(static_cast<size_t>(num_layers) * 4, -1);
        for (int i = 0; i < static_cast<int>(dec_in_names.size()); ++i) {
            int layer = 0;
            int kind = kv_kind(dec_in_names[i], "past_key_values", &layer);
            if (kind >= 0) kv_in_idx[static_cast<size_t>(layer) * 4 + kind] = i;
        }
        for (int i = 0; i < static_cast<int>(dec_out_names.size()); ++i) {
            int layer = 0;
            int kind = kv_kind(dec_out_names[i], "present", &layer);
            if (kind >= 0) present_out_idx[static_cast<size_t>(layer) * 4 + kind] = i;
        }
        for (int slot = 0; slot < num_layers * 4; ++slot) {
            if (kv_in_idx[slot] < 0 || present_out_idx[slot] < 0)
                throw std::runtime_error("incomplete past_key_values interface");
        }

        // Derive KV head count and head dim from a past tensor: [batch, heads, past, dim].
        // Keep the ConstTypeInfo alive: its tensor info is a view owned by it.
        Ort::TypeInfo kv_type = decoder->GetInputTypeInfo(kv_in_idx[0]);
        auto shape = kv_type.GetTensorTypeAndShapeInfo().GetShape();
        if (shape.size() != 4 || shape[1] <= 0 || shape[3] <= 0) {
            std::string msg = "cannot derive KV shape (dims:";
            for (auto d : shape) msg += " " + std::to_string(d);
            msg += ")";
            throw std::runtime_error(msg);
        }
        num_heads = static_cast<int>(shape[1]);
        head_dim = static_cast<int>(shape[3]);
    }
};

// Runs the model on one chunk (<= 64 s) and returns text + inference seconds.
std::string transcribe(Model &m, const Tokenizer &tok, const int16_t *pcm, size_t n_samples,
                       int max_tokens, double *infer_s) {
    const auto t_start = std::chrono::steady_clock::now();

    std::vector<float> f32(n_samples);
    for (size_t i = 0; i < n_samples; ++i) f32[i] = static_cast<float>(pcm[i]) / 32768.0f;

    std::vector<int64_t> in_shape{1, static_cast<int64_t>(n_samples)};
    std::vector<int64_t> mask(n_samples, 1);
    std::vector<const char *> enc_names;
    std::vector<Ort::Value> enc_vals;
    enc_names.push_back(m.enc_in_names[m.enc_input_values].c_str());
    enc_vals.push_back(Ort::Value::CreateTensor<float>(m.mem, f32.data(), f32.size(),
                                                       in_shape.data(), in_shape.size()));
    if (m.enc_attention_mask >= 0) {
        enc_names.push_back(m.enc_in_names[m.enc_attention_mask].c_str());
        enc_vals.push_back(Ort::Value::CreateTensor<int64_t>(m.mem, mask.data(), mask.size(),
                                                             in_shape.data(), in_shape.size()));
    }

    std::vector<const char *> enc_out_names;
    for (const auto &n : m.enc_out_names) enc_out_names.push_back(n.c_str());
    auto enc_outs = m.encoder->Run(Ort::RunOptions{nullptr}, enc_names.data(), enc_vals.data(),
                                   enc_vals.size(), enc_out_names.data(),
                                   enc_out_names.size());
    Ort::Value hidden = std::move(enc_outs[m.enc_hidden_out]);
    auto hshape = hidden.GetTensorTypeAndShapeInfo().GetShape();
    size_t hcount = 1;
    for (auto d : hshape) hcount *= static_cast<size_t>(d);
    float *hdata = hidden.GetTensorMutableData<float>();

    // Empty past KV tensors: [0, heads, 1, head_dim].
    const std::vector<int64_t> zero_shape{0, m.num_heads, 1, m.head_dim};
    static float zero_dummy = 0.0f;
    std::vector<Ort::Value> past(static_cast<size_t>(m.num_layers) * 4);
    for (auto &v : past) {
        v = Ort::Value::CreateTensor<float>(m.mem, &zero_dummy, 0, zero_shape.data(),
                                            zero_shape.size());
    }

    const std::vector<int64_t> id_shape{1, 1};
    const std::vector<int64_t> cache_shape{1};
    std::vector<const char *> dec_names, dec_out_names;
    for (const auto &n : m.dec_in_names) dec_names.push_back(n.c_str());
    for (const auto &n : m.dec_out_names) dec_out_names.push_back(n.c_str());

    std::vector<int> tokens;
    tokens.reserve(static_cast<size_t>(max_tokens));
    int64_t cur = kStartToken;
    for (int step = 0; step < max_tokens; ++step) {
        const bool use_cache = step > 0;
        int64_t id = cur;
        bool uc = use_cache;

        std::vector<Ort::Value> vals(dec_names.size());
        vals[m.dec_input_ids] = Ort::Value::CreateTensor<int64_t>(m.mem, &id, 1, id_shape.data(),
                                                                  id_shape.size());
        vals[m.dec_hidden] = Ort::Value::CreateTensor<float>(m.mem, hdata, hcount, hshape.data(),
                                                             hshape.size());
        vals[m.dec_use_cache] = Ort::Value::CreateTensor<bool>(m.mem, &uc, 1, cache_shape.data(),
                                                               cache_shape.size());
        if (m.dec_encoder_mask >= 0) {
            vals[m.dec_encoder_mask] = Ort::Value::CreateTensor<int64_t>(
                m.mem, mask.data(), mask.size(), in_shape.data(), in_shape.size());
        }
        for (int slot = 0; slot < m.num_layers * 4; ++slot) {
            vals[m.kv_in_idx[slot]] = std::move(past[slot]);
        }

        auto outs = m.decoder->Run(Ort::RunOptions{nullptr}, dec_names.data(), vals.data(),
                                   vals.size(), dec_out_names.data(), dec_out_names.size());

        auto lshape = outs[m.dec_logits].GetTensorTypeAndShapeInfo().GetShape();
        if (lshape.size() != 3) throw std::runtime_error("unexpected logits rank");
        const int64_t seq = lshape[1];
        const int64_t vocab = lshape[2];
        const float *row = outs[m.dec_logits].GetTensorMutableData<float>() + (seq - 1) * vocab;
        int best = 0;
        float best_v = row[0];
        for (int64_t k = 1; k < vocab; ++k) {
            if (row[k] > best_v) {
                best_v = row[k];
                best = static_cast<int>(k);
            }
        }
        tokens.push_back(best);

        for (int slot = 0; slot < m.num_layers * 4; ++slot) {
            const int kind = slot % 4;
            if (!use_cache || kind < 2) {
                past[slot] = std::move(outs[m.present_out_idx[slot]]);
            } else {
                // Encoder KV does not change after the first step: reuse it.
                past[slot] = std::move(vals[m.kv_in_idx[slot]]);
            }
        }

        if (best == kEosToken) break;
        cur = best;
    }

    *infer_s = std::chrono::duration<double>(std::chrono::steady_clock::now() - t_start).count();
    return tok.decode(tokens);
}

std::string basename_of(const std::string &p) {
    size_t end = p.find_last_not_of('/');
    if (end == std::string::npos) return p;
    size_t s = p.find_last_of('/', end);
    return p.substr(s == std::string::npos ? 0 : s + 1, end - (s == std::string::npos ? 0 : s + 1) + 1);
}

void usage(FILE *f) {
    std::fputs("usage: stt-adapter-moonshine [--model DIR] [--encoder FILE] [--decoder FILE]\n"
               "       [--vocab FILE] [--threads N] [--max-tokens N]\n",
               f);
}

} // namespace

int main(int argc, char **argv) {
    Options o;
    std::string model_arg;
    for (int i = 1; i < argc; ++i) {
        auto need = [&](const char *flag) -> const char * {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "stt-adapter-moonshine: %s needs a value\n", flag);
                std::exit(2);
            }
            return argv[++i];
        };
        if (std::strcmp(argv[i], "--model") == 0) model_arg = need("--model");
        else if (std::strcmp(argv[i], "--encoder") == 0) o.encoder = need("--encoder");
        else if (std::strcmp(argv[i], "--decoder") == 0) o.decoder = need("--decoder");
        else if (std::strcmp(argv[i], "--vocab") == 0) o.vocab = need("--vocab");
        else if (std::strcmp(argv[i], "--threads") == 0) o.threads = std::atoi(need("--threads"));
        else if (std::strcmp(argv[i], "--max-tokens") == 0) o.max_tokens = std::atoi(need("--max-tokens"));
        else if (std::strcmp(argv[i], "-h") == 0 || std::strcmp(argv[i], "--help") == 0) {
            usage(stdout);
            return 0;
        } else {
            std::fprintf(stderr, "stt-adapter-moonshine: unknown argument: %s\n", argv[i]);
            usage(stderr);
            return 2;
        }
    }
    if (!model_arg.empty()) o.model_dir = model_arg;
    if (o.threads <= 0) o.threads = 4;
    if (o.max_tokens <= 0) o.max_tokens = kDefaultMaxTokens;
    if (o.encoder.empty()) o.encoder = o.model_dir + "/encoder_model.onnx";
    if (o.decoder.empty()) o.decoder = o.model_dir + "/decoder_model_merged.onnx";
    if (o.vocab.empty()) o.vocab = o.model_dir + "/vocab.tsv";

    // Protocol header must be read before loading the model (nucleus sends it
    // immediately after spawn; see CONTRATOS §2.2).
    std::string header;
    if (!read_line(stdin, header) || header.find('{') == std::string::npos) {
        emit_error("protocol", "missing stt-adapter/1 header line", true);
        return 1;
    }
    long rate = 0, channels = 0;
    json_int(header, "rate", &rate);
    if (!json_int(header, "channels", &channels)) channels = 1;
    if (rate != kSampleRate || channels != kChannels) {
        emit_error("audio", "unsupported audio format: Moonshine adapter needs s16le/16000/mono",
                   true);
        return 1;
    }

    try {
        Tokenizer tok;
        std::string err;
        if (!tok.load(o.vocab, &err)) {
            emit_error("model", err, true);
            return 1;
        }

        const auto t_load = std::chrono::steady_clock::now();
        Model model(o.encoder, o.decoder, o.threads);
        const double load_s =
            std::chrono::duration<double>(std::chrono::steady_clock::now() - t_load).count();
        std::fprintf(stderr,
                     "stt-adapter-moonshine: loaded %s in %.2fs (threads=%d, layers=%d, "
                     "kv_heads=%d, head_dim=%d)\n",
                     o.model_dir.c_str(), load_s, o.threads, model.num_layers, model.num_heads,
                     model.head_dim);

        std::printf("{\"type\":\"ready\",\"protocol\":\"stt-adapter/1\",\"name\":\"moonshine\","
                    "\"model\":\"%s\",\"audio\":{\"rate\":16000,\"channels\":1,\"format\":"
                    "\"s16le\"},\"capabilities\":[\"final\"]}\n",
                    basename_of(o.model_dir).c_str());
        std::fflush(stdout);

        unsigned char lenbuf[4];
        std::vector<unsigned char> payload;
        long long total_bytes = 0;
        int frame = 0;
        double total_infer = 0.0;
        while (read_full(stdin, lenbuf, 4)) {
            const uint32_t n = static_cast<uint32_t>(lenbuf[0]) |
                               (static_cast<uint32_t>(lenbuf[1]) << 8) |
                               (static_cast<uint32_t>(lenbuf[2]) << 16) |
                               (static_cast<uint32_t>(lenbuf[3]) << 24);
            payload.resize(n);
            if (n > 0 && !read_full(stdin, payload.data(), n)) {
                emit_error("protocol", "truncated PCM frame payload", true);
                return 1;
            }

            const double t0 = static_cast<double>(total_bytes) / (kSampleRate * kBytesPerSample);
            const double t1 = t0 + static_cast<double>(n) / (kSampleRate * kBytesPerSample);

            const size_t n_samples = n / kBytesPerSample;
            std::string text;
            double infer_s = 0.0;
            if (n_samples >= static_cast<size_t>(kMinAudioS * kSampleRate)) {
                const int16_t *pcm = reinterpret_cast<const int16_t *>(payload.data());
                const size_t chunk = static_cast<size_t>(kChunkAudioS * kSampleRate);
                for (size_t off = 0; off < n_samples; off += chunk) {
                    const size_t len = std::min(chunk, n_samples - off);
                    double part_s = 0.0;
                    std::string part =
                        transcribe(model, tok, pcm + off, len, o.max_tokens, &part_s);
                    infer_s += part_s;
                    for (size_t trim = kRetryTrimSamples;
                         part.empty() && trim <= kRetryTrimS * kRetryTrimSamples;
                         trim += kRetryTrimSamples) {
                        const size_t cap = std::min(trim, len / 4);
                        part = transcribe(model, tok, pcm + off + cap, len - 2 * cap,
                                          o.max_tokens, &part_s);
                        infer_s += part_s;
                    }
                    if (!part.empty()) {
                        if (!text.empty()) text.push_back(' ');
                        text += part;
                    }
                }
            }
            total_infer += infer_s;

            const double dur = static_cast<double>(n_samples) / kSampleRate;
            const double rtf = dur > 0.0 ? infer_s / dur : 0.0;
            std::fputs("{\"type\":\"final\",\"text\":\"", stdout);
            json_escape(stdout, text);
            std::fprintf(stdout, "\",\"frame\":%d,\"t0\":%.3f,\"t1\":%.3f,\"rtf\":%.3f}\n", frame,
                         t0, t1, rtf);
            std::fflush(stdout);

            total_bytes += n;
            ++frame;
        }

        const double audio_s = static_cast<double>(total_bytes) / (kSampleRate * kBytesPerSample);
        struct rusage ru {};
        if (getrusage(RUSAGE_SELF, &ru) != 0) ru.ru_maxrss = 0;
        std::fprintf(stdout,
                     "{\"type\":\"bye\",\"frames\":%d,\"bytes\":%lld,\"audio_s\":%.3f,"
                     "\"infer_s\":%.3f,\"rss_kb\":%ld}\n",
                     frame, total_bytes, audio_s, total_infer, static_cast<long>(ru.ru_maxrss));
        std::fflush(stdout);
        return 0;
    } catch (const Ort::Exception &e) {
        emit_error("model", std::string("onnxruntime: ") + e.what(), true);
        return 1;
    } catch (const std::exception &e) {
        emit_error("model", e.what(), true);
        return 1;
    }
}
